CREATE TRIGGER active_scene_scope BEFORE UPDATE OF active_version_id ON scenes WHEN NEW.active_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM scene_versions v JOIN projects p ON p.id=v.project_id WHERE v.id=NEW.active_version_id AND v.scene_id=NEW.id AND v.project_id=NEW.project_id AND v.status='APPROVED' AND p.active_script_version_id=v.script_version_id) BEGIN SELECT RAISE(ABORT,'ACTIVE_SCENE_INVALID'); END;
